import pytest
import click
from click.shell_completion import CompletionItem

class Foo(click.ParamType):
    def convert(self, value, param, ctx):
        return value

    def shell_complete(self, ctx, param, incomplete):
        return [
            CompletionItem(value=value, help="adsf") for value in 
            ["baz:quux", "spam:eggs"]
        ]

@click.command()
@click.argument("foo", type=Foo())
def main(foo):
    print(foo)

def test_shell_completion_colon_handling(runner):
    result = runner.invoke(main, ['foo', 'baz'])
    assert result.output.strip() == 'baz:quux'

import pytest
import click

def test_backspace_behavior(runner, monkeypatch):
    @click.command()
    def cli():
        return click.prompt("Enter text", default="test")

    monkeypatch.setattr(click._compat, "isatty", lambda _: True)
    result = runner.invoke(cli, input="te\x08st\n")  # Simulate backspace
    assert result.output.strip() == "Enter text: test"

