import pytest
import click
from click import ParamType

class MyClass(ParamType):
    name = "myclass"

    @staticmethod
    def from_str(input: str) -> 'MyClass':
        if input != 'works':
            raise ValueError(f'input was {input=}, should be works')
        return MyClass()

@pytest.fixture
def runner():
    return click.testing.CliRunner()

def test_func_param_type_value_error(runner):
    @click.command()
    @click.argument("mydata", type=MyClass())
    def test_command(mydata):
        click.echo(f"mydata={mydata}")

    result = runner.invoke(test_command, ["fail"])
    assert result.exit_code != 0
    assert "input was value='fail', should be works" in result.output

import pytest
from jinja2 import Environment

@pytest.fixture
def env_async():
    return Environment(enable_async=True)

def test_custom_filter_coroutine_error(env_async):
    env_async.filters.update({'add_two': lambda x, y: [i + y for i in x]})
    tmpl = env_async.from_string("{% for item in a.b|add_two(5)[:1] %}{{ item }}{% endfor %}")
    a = dict(b=[1, 2, 3])
    with pytest.raises(TypeError, match="'coroutine' object is not subscriptable"):
        tmpl.render(a=a)
